CREATE TABLE IF NOT EXISTS chat_group_policy(conversation_id BIGINT UNSIGNED PRIMARY KEY,require_approval TINYINT NOT NULL DEFAULT 0,member_name TINYINT NOT NULL DEFAULT 1,member_avatar TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS chat_group_membership(conversation_id BIGINT UNSIGNED NOT NULL,user_id VARCHAR(191) NOT NULL,role ENUM('member','admin') NOT NULL DEFAULT 'member',state ENUM('active','left','removed') NOT NULL DEFAULT 'active',muted_until DATETIME NULL,PRIMARY KEY(conversation_id,user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS chat_group_invitations(conversation_id BIGINT UNSIGNED NOT NULL,user_id VARCHAR(191) NOT NULL,invited_by VARCHAR(191) NOT NULL,username VARCHAR(150) NOT NULL,display_name VARCHAR(150) NOT NULL,is_admin TINYINT NOT NULL DEFAULT 0,PRIMARY KEY(conversation_id,user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
